{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-ARkz8w/src/policy.js","content":"/**
 * Per-key state machines for the two limiter kinds. Both expose the same
 * three-step protocol the engine drives: advance the key to a tick, ask
 * whether it currently allows a request, and record one that was allowed.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capUnits = capacity * per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: this.capUnits, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const grown = state.numerator + this.refill * elapsed
      state.numerator = grown > this.capUnits ? this.capUnits : grown
      state.lastTick = tick
    }
  }

  canAllow(key) {
    return this.#state(key).numerator >= this.per
  }

  record(key) {
    this.#state(key).numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const cutoff = tick - this.span
    let drop = 0
    while (drop < state.length && state[drop] <= cutoff) drop++
    if (drop > 0) state.splice(0, drop)
  }

  canAllow(key) {
    return BigInt(this.#state(key).length) < this.limit
  }

  record(key) {
    this.#state(key).push(0n)
  }
}
"}

