{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-ARkz8w/src/parse.js","content":"/**
 * Parses a limiter file into declared policies, routes and events, or
 * throws a `ParseError` describing the first line that fails to conform.
 */

import { TokenBucket, SlidingWindow } from './policy.js'

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const INTEGER_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function isName(token) {
  return TOKEN_RE.test(token)
}

function parseField(token, field, least) {
  if (!INTEGER_RE.test(token) || BigInt(token) < least) {
    throw new Error(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(token)
}

/**
 * @returns {{ policies: Map, routes: Array<{prefix: string, names: string[], policies: object[]}>, events: Array<{tick: bigint, key: string}> }}
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue

    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    try {
      if (directive === 'bucket' || directive === 'window' || directive === 'route') {
        if (seenEvent) throw new Error('declarations must come before the first event')
      }

      if (directive === 'bucket') {
        if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [, name, capacityStr, refillStr, perStr] = tokens
        if (!isName(name)) throw new Error(`invalid policy name ${name}`)
        const capacity = parseField(capacityStr, 'capacity', 1n)
        const refill = parseField(refillStr, 'refill', 0n)
        const per = parseField(perStr, 'per', 1n)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, new TokenBucket(capacity, refill, per))
      } else if (directive === 'window') {
        if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
        const [, name, limitStr, spanStr] = tokens
        if (!isName(name)) throw new Error(`invalid policy name ${name}`)
        const limit = parseField(limitStr, 'limit', 0n)
        const span = parseField(spanStr, 'span', 1n)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        policies.set(name, new SlidingWindow(limit, span))
      } else if (directive === 'route') {
        if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
        const prefix = tokens[1]
        const names = tokens.slice(2)
        if (!isName(prefix)) throw new Error(`invalid route prefix ${prefix}`)
        if (routePrefixes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
        const routePolicies = []
        for (const name of names) {
          const policy = policies.get(name)
          if (policy === undefined) throw new Error(`unknown policy ${name}`)
          routePolicies.push(policy)
        }
        routePrefixes.add(prefix)
        routes.push({ prefix, names, policies: routePolicies })
      } else if (directive === 'event') {
        if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
        const [, tickStr, key] = tokens
        if (!isName(key)) throw new Error(`invalid key ${key}`)
        const tick = parseField(tickStr, 'tick', 0n)
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        lastTick = tick
        seenEvent = true
        events.push({ tick, key })
      } else {
        throw new Error(`unknown directive ${directive}`)
      }
    } catch (err) {
      throw new ParseError(lineNo, err.message)
    }
  }

  routes.sort((a, b) => b.prefix.length - a.prefix.length)
  return { policies, routes, events }
}
"}

