    if (!route.policies[i].canAllow(key)) {
      deniedBy = route.names[i]
      break
    }
  }

  if (deniedBy === null) {
    for (const policy of route.policies) policy.record(key, tick)
    return { allow: true, deniedBy: null }
  }
  return { allow: false, deniedBy }
