  const lines = []
  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    const verdict = verdictFor(route, tick, key)
    lines.push(
      verdict.allow ? `${tick} ${key} allow` : `${tick} ${key} deny ${verdict.deniedBy}`
    )
  }
  return lines.map((line) => line + '\n').join('')
