  const totals = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    const verdict = verdictFor(route, tick, key)
    let entry = totals.get(key)
    if (entry === undefined) {
      entry = { allowed: 0n, denied: 0n }
      totals.set(key, entry)
    }
    if (verdict.allow) {
      entry.allowed += 1n
      totalAllowed += 1n
    } else {
      entry.denied += 1n
      totalDenied += 1n
    }
  }

  const keys = [...totals.keys()].sort()
  const lines = keys.map((key) => {
    const entry = totals.get(key)
    return `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
